//! Adventurer's Guide (AG) shared spell list.
//!
//! Generated by `src/bin/ingest_spells.rs` (config-driven, all
//! books) from the real `pathfinder/paizo/roleplaying_game/adventurers_guide/ag_spells.lst` corpus. Record coverage: every
//! real, active (non-`.MOD`, non-`.COPY=`) base spell declaration.
//!
//! `level` is the minimum level across the record's `CLASSES:`/
//! `DOMAINS:` token(s), `None` for the rare record that states
//! neither (never fabricated -- these land `text-complete`, not
//! `ingested-magnitude`, via `v06_work_inventory::classify`'s
//! existing `Some(false)` branch).
//!
//! `school`/`description` are `Option` because a minority of
//! records carry neither token of their own on this book's base
//! row.

/// The full 9-school PF1 spell-school enum, mirroring every other book's
/// own copy exactly.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Pf1SchoolId {
    Abjuration,
    Conjuration,
    Divination,
    Enchantment,
    Evocation,
    Illusion,
    Necromancy,
    Transmutation,
    Universal,
}

impl Pf1SchoolId {
    pub fn from_corpus_str(raw: &str) -> Option<Self> {
        match raw {
            "Abjuration" => Some(Pf1SchoolId::Abjuration),
            "Conjuration" => Some(Pf1SchoolId::Conjuration),
            "Divination" => Some(Pf1SchoolId::Divination),
            "Enchantment" => Some(Pf1SchoolId::Enchantment),
            "Evocation" => Some(Pf1SchoolId::Evocation),
            "Illusion" => Some(Pf1SchoolId::Illusion),
            "Necromancy" => Some(Pf1SchoolId::Necromancy),
            "Transmutation" => Some(Pf1SchoolId::Transmutation),
            "Universal" => Some(Pf1SchoolId::Universal),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SpellListEntry {
    pub key: &'static str,
    /// `decisions.md §24`: `Some(line)` ONLY when `key` above
    /// is a Codex-generated neutral identity (the row's real
    /// name is Product Identity) -- carries the real citation
    /// line so `cache_gen::spell_lane_dump` can resolve it
    /// without a name-based lookup. `None` for an ordinary entry.
    pub name_pi_line: Option<u32>,
    pub school: Option<Pf1SchoolId>,
    pub level: Option<u8>,
    pub description: Option<&'static str>,
}

pub const SPELL_LIST: &[SpellListEntry] = &[
    SpellListEntry { key: "Absorb Rune I", name_pi_line: None, school: Some(Pf1SchoolId::Abjuration), level: Some(4), description: Some("This spell allows you to lay your hand upon a magical glyph, symbol, or other magical spell effect (referred to in this spell description as a \"rune\") and attempt to absorb the essence of its effect. To absorb a rune, you must be aware of the rune's existence (but need not know the details of what it actually does) and then succeed at a caster level check (DC = 10 + the caster level of the spell affect being absorbed) as you touch the rune in question. If you fail this caster level check, the magical rune is not triggered unless you fail the roll by 5 or more. If you succeed at the caster level check, the rune is removed from the surface it was originally placed upon and duplicated on the cloth of a silk glove worn on your hand. The rune remains located on the glove's palm in an inert state for up to (CASTERLEVEL) minutes. As a standard action taken at any time during that duration, you can transfer the rune to another surface similar to the one it was originally placed upon, at which point the rune's function either returns to normal or dissipates harmlessly as if successfully dispelled (your choice). If the spell's duration expires before you place the rune on a new surface, the absorbed rune dissipates harmlessly. Absorb rune I affects only runes whose effects are equivalent to a spell of 3rd level or lower. An attempt to use absorb rune I on a more powerful effect automatically triggers the rune when you touch it. [Material Components] a white silk glove worth 25 gp.") },
    SpellListEntry { key: "Absorb Rune II", name_pi_line: None, school: Some(Pf1SchoolId::Abjuration), level: Some(6), description: Some("This spell allows you to lay your hand upon a magical glyph, symbol, or other magical spell effect (referred to in this spell description as a \"rune\") and attempt to absorb the essence of its effect. To absorb a rune, you must be aware of the rune's existence (but need not know the details of what it actually does) and then succeed at a caster level check (DC = 10 + the caster level of the spell affect being absorbed) as you touch the rune in question. If you fail this caster level check, the magical rune is not triggered unless you fail the roll by 5 or more. If you succeed at the caster level check, the rune is removed from the surface it was originally placed upon and duplicated on the cloth of a silk glove worn on your hand. The rune remains located on the glove's palm in an inert state for up to (CASTERLEVEL) minutes. As a standard action taken at any time during that duration, you can transfer the rune to another surface similar to the one it was originally placed upon, at which point the rune's function either returns to normal or dissipates harmlessly as if successfully dispelled (your choice). If the spell's duration expires before you place the rune on a new surface, the absorbed rune dissipates harmlessly. Absorb rune II affects only runes whose effects are equivalent to a spell of 5th level or lower. An attempt to use absorb rune II on a more powerful effect automatically triggers the rune when you touch it. [Material Components] a white silk glove worth 25 gp.") },
    SpellListEntry { key: "Absorb Rune III", name_pi_line: None, school: Some(Pf1SchoolId::Abjuration), level: Some(9), description: Some("This spell allows you to lay your hand upon a magical glyph, symbol, or other magical spell effect (referred to in this spell description as a \"rune\") and attempt to absorb the essence of its effect. To absorb a rune, you must be aware of the rune's existence (but need not know the details of what it actually does) and then succeed at a caster level check (DC = 10 + the caster level of the spell affect being absorbed) as you touch the rune in question. If you fail this caster level check, the magical rune is not triggered unless you fail the roll by 5 or more. If you succeed at the caster level check, the rune is removed from the surface it was originally placed upon and duplicated on the cloth of a silk glove worn on your hand. The rune remains located on the glove's palm in an inert state for up to (CASTERLEVEL) minutes. As a standard action taken at any time during that duration, you can transfer the rune to another surface similar to the one it was originally placed upon, at which point the rune's function either returns to normal or dissipates harmlessly as if successfully dispelled (your choice). If the spell's duration expires before you place the rune on a new surface, the absorbed rune dissipates harmlessly. Absorb rune III affects only runes whose effects are equivalent to a spell of 8th level or lower. An attempt to use absorb rune III on a more powerful effect automatically triggers the rune when you touch it. [Material Components] a white silk glove worth 25 gp.") },
    SpellListEntry { key: "Codex-Named Unit (spell_adventurers_guide_ag_spells_lst_4)", name_pi_line: Some(4), school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("[redacted PI]") },
    SpellListEntry { key: "Blade of Light", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("This spell infuses a weapon with pure sunlight (the weapon need not be a bladed weapon). A weapon enhanced by this spell sheds light as if daylight had been cast on it. It functions as a magic and good weapon for the purposes of overcoming damage reduction. The weapon grants a +2 sacred bonus on attack rolls against undead and deals +1d6 points of damage on a successful hit against such foes; against incorporeal undead, it functions as if it had the ghost touch weapon special ability. The weapon automatically confirms critical hits against foes that are vulnerable to sunlight.") },
    SpellListEntry { key: "Bone Flense", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("[redacted PI]") },
    SpellListEntry { key: "Brand of Conformity", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(1), description: Some("This spell etches the symbol of a nation, organization, or order on the target, dealing 1 point of damage. The mark can be placed on any exposed portion of the creature, typically the head or forearm. While branded in this way, the recipient loses the ability to speak or understand its racial language and the language of its homeland or primary culture (if these are different). For example, an elf raised among the Shoanti would lose Elven and Shoanti (if she knew both those languages), while a halfling raised among dwarves would lose both Halfling and Dwarven (if she knew both those languages). A gnome raised among gnomes would lose Gnome, but no other language. This spell never suppresses Common or Undercommon, nor does it prevent spellcasting, though it may prevent a target from speaking intelligibly if it suppresses all of the target's languages. A brand of conformity can be hidden beneath clothing or removed by scraping it away (the latter deals 1d6 points of damage, though the brand returns if that damage is healed). In any event, the language-suppression element of a brand of conformity continues to function even when hidden or scraped away.") },
    SpellListEntry { key: "Brand of Hobbling", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("This spell etches a symbol of chains, a particular prison, or a lawful institution on the target, dealing 1d6 points of damage. The mark can be placed on any exposed portion of the creature, typically on the head or forearm. While the recipient is branded in this way, all of its movement speeds are reduced by half (rounded down to the next 5-foot increment). A brand of hobbling can be hidden by clothing or removed by scraping the brand away (the latter deals 1d6 points of damage, though the brand returns if that damage is healed), but in either case the effects of a brand of hobbling continue to function.") },
    SpellListEntry { key: "Brand of Tracking", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("This spell etches the symbol of an eye or a lawful institution on the target, dealing 1d6 points of damage. The mark can be placed on any exposed portion of the creature, typically the head or forearm. While the target is branded in this way, twice per day as a standard action, you can instantly determine in what direction and how far away the target is, as long as it is within (CASTERLEVEL) miles. If the target travels beyond this range or to another plane, you cannot gain information about the recipient's location. Similarly, if the target becomes warded by a spell or effect that thwarts divination spells (such as nondetection) or moves into such an area (such as one created by antimagic field), you cannot gain information about the target's location. This effect otherwise works as a locate creature spell that lasts for (CASTERLEVEL) minutes. It can be fooled by mislead but not by polymorph. A brand of tracking can be hidden by clothing or temporarily removed by scraping it away (the latter deals 1d6 points of damage, though the brand returns if that damage is healed, or 1 day later otherwise). The effects of a brand of tracking continue to function even when hidden or scraped away. A brand of tracking cannot be dispelled, but it can be permanently removed by any means that removes a mark of justice (see page 312 of the Pathfinder RPG Core Rulebook).") },
    SpellListEntry { key: "Brightest Light", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(4), description: Some("[redacted PI]") },
    SpellListEntry { key: "Burning Sands", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(1), description: Some("You cause sheets of hot sand to spread over the ground in the area of effect. This layer of sand is 1 foot deep and constantly shifts and churns, transforming the ground in the area into difficult terrain. The sand itself burns, and periodic flames rise from the grit. While these flames cannot ignite objects, they deal 1d4 points of fire damage to any creature that ends its turn in contact with the ground within the area of effect. At the end of the duration, the sand vanishes, leaving no aftereffects (other than damage dealt).") },
    SpellListEntry { key: "Cleansing Fire", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(4), description: Some("A ring of fire surrounds the area affected by the spell. The flames radiate heat, but not enough to damage adjacent creatures. The flames deal 2d6 points of fire damage to any creatures that pass through them (or 4d6 points of damage to undead creatures). If you manifest a portion of the ring in a square that contains a creature, that creature takes damage as if it passed through the ring. The ring of flames attempts to dispel all ongoing spell effects with the evil descriptor within it, targeting each spell effect once per round as per dispel magic. Any attempt to cast a spell with the evil descriptor inside the ring of flames is targeted by a dispel magic affect that attempts to counterspell the evil spell.") },
    SpellListEntry { key: "Contest of Skill", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("[redacted PI]") },
    SpellListEntry { key: "Crimson Breath", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("When you cast this spell, your salivary glands transform and instantly fill with potent venom. Make a ranged touch attack against a single target in range; if you hit, the target is affected by a dose of breath of the mantis god (see page 158). The Fortitude save DC for this poison is the same as the spell's DC, not the standard save DC for the poison.") },
    SpellListEntry { key: "Deceptive Redundancy", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(5), description: Some("You create a contingent ward that defies those who would dispel your magic, convincing them that their spell worked. When a spell such as dispel magic would end one of your spells that's affecting you, you can dismiss deceptive redundancy as an immediate action to attempt an opposed caster level check against the spellcaster. If you succeed, the dispelling effect fails to end your spell, and your spell's aura becomes difficult to detect for (CASTERLEVEL) rounds. Any divination attempted during this time fails to perceive the spell's aura unless the caster succeeds at a caster level check (DC (CASTERLEVEL+15)). Deceptive redundancy is most effective when hiding auras for spells that don't have easily perceived effects, rather than visually obvious spells such as enlarge person or fire shield.") },
    SpellListEntry { key: "Codex-Named Unit (spell_adventurers_guide_ag_spells_lst_16)", name_pi_line: Some(16), school: Some(Pf1SchoolId::Transmutation), level: Some(1), description: Some("[redacted PI]") },
    SpellListEntry { key: "Detect Charm", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(1), description: Some("This spell functions as per detect magic, except that it detects only charm, compulsion, and possession effects. You immediately detect the strength and location of each such aura on all creatures in the area. You can attempt to identify the properties of each aura (see Spellcraft on page 106 the Pathfinder RPG Core Rulebook). In addition to noticing the targets of these effects, you can recognize when creatures in the area are using these effects on others by attempting a Sense Motive check as a standard action (DC = 20 + caster level). If you succeed, you can attempt a Spellcraft check to identify what magic it is using (even if the target is not in the area).") },
    SpellListEntry { key: "Detoxify", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("You remove a creature's ability to poison others, whether inherent or via poisoned weapons. Whenever an affected creature would inflict poison with an attack, spell, or other method (including auras and other constant methods), that poison is automatically neutralized. This does not grant the subject of the spell any resistance to poison itself.") },
    SpellListEntry { key: "Dirge of the Victorious Knights", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(6), description: Some("[redacted PI]") },
    SpellListEntry { key: "Frost Mammoth", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(6), description: Some("A blast of snow suddenly fills an area with a space of 15 feet, immediately taking the shape of a woolly mammoth made of snow with tusks of solid ice. The mammoth has statistics identical to those of a mastodon (Pathfinder RPG Bestiary 128), except it also has the cold subtype (and thus gains immunity to cold and vulnerability to fire). The frost mammoth obeys your telepathic commands. It allows you or anyone you designate to ride it, and it is treated as if combat trained. At 17th level, a frost mammoth you conjure deals an additional 1d6 points of cold damage with each physical attack.") },
    SpellListEntry { key: "Haunting Reminder", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(1), description: Some("As part of casting this spell, you can attempt a single Intimidate check to make the target act friendly to you. If you succeed, the target assists you normally, but it remains fearful of your retribution even after its attitude shifts to unfriendly. If the creature reports your coercion to authorities, attacks you, or otherwise acts in a purposeful way that threatens you or your objectives (at the GM's discretion), the spell triggers, inflicting the creature with the unshakable certainty that you will find and punish it. This imposes the shaken condition on the creature for (CASTERLEVEL) days; during this time, the creature takes a -2 penalty on saving throws against spells you cast with the fear descriptor.") },
    SpellListEntry { key: "Hidden Knowledge", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("[redacted PI]") },
    SpellListEntry { key: "Infernal Challenger", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(3), description: Some("[redacted PI]") },
    SpellListEntry { key: "Instant Portrait", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(1), description: Some("You touch a surface and produce a painted portrait of either yourself or a creature you can see without needing to attempt a Craft (painting) check. The surface to be affected must be relatively flat, such as a piece of paper or a wall. The image can be any color of your choice, but is monochromatic. While it is of too poor a quality to sell, it is otherwise accurate enough to recognize the subject or to serve as a target for the enter image spell. The portrait reflects your perception of the creature depicted, including any disguises, magical or mundane, that the subject is wearing at the time of the painting's creation. The portrait is only as durable as normal paint and can be removed by mundane means.") },
    SpellListEntry { key: "Invoke Primal Power", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("[redacted PI]") },
    SpellListEntry { key: "Mark of Blood", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("You place a drop of your blood on a weapon and charge it with magic so that you transfer a small amount of your life essence to the next living creature you strike with the weapon. Thereafter, you can spend a move action to know the direction and general distance of that creature. The target can negate this effect with a successful Will save. You must strike a creature within 1 minute of casting this spell or the magic is wasted, but once the mark of blood takes effect it is permanent until dispelled or removed via an effect like remove curse.") },
    SpellListEntry { key: "Mask from Divination", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(4), description: Some("As part of the action used to cast this spell, you place the mask used as the focus component on the target's face, after which it adheres tightly to the target for the spell's duration and cannot be removed by physical force. Despite lacking eyes, this mask does not impair its wearer's vision in any way. While in effect, this spell functions like nondetection, except it also foils divination spells that attempt to gather information about the creature, even if they don't target it specifically. In the case of divination spells that would normally reveal the wearer's presence, such as see invisibility, the spell works, but the wearer is detected only if the caster succeeds at a caster level check. Likewise, scrying attempts that specifically target the wearer do not work at all unless the caster succeeds at a caster level check. In addition, the DCs of skill checks to learn about the wearer or identify the wearer and its strengths and weaknesses-including Diplomacy checks to gather information, Perception checks opposed by the target's Disguise checks, and Knowledge checks-increase by 4. The mask cannot be removed for the duration of the spell, and the fact that the target is wearing the focus mask cannot be hidden in any way from creatures that observe the target. [Material Components] diamond dust worth 200 gp") },
    SpellListEntry { key: "Mirror Mantis", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(1), description: Some("[redacted PI]") },
    SpellListEntry { key: "Obscured Script", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(2), description: Some("You create a latent illusion that clouds the judgment and reading ability of any creature that examines a targeted text. While casting the spell, you can designate up to (CASTERLEVEL) creatures other than yourself to be immune to the effects. All other creatures that read the text must succeed at a Will save or find it difficult to properly parse and decipher the contents. This increases the DC of Linguistics checks to decipher the text by (min(10,CASTERLEVEL)), and it increases the DC of the Wisdom check to avoid drawing a false conclusion by an equal amount. Unaffected creatures gain a +(min(10,CASTERLEVEL)) circumstance bonus on Bluff checks to deceive affected creatures about the text's contents. The spell obscures any magical glyphs, runes, or symbols within the text, increasing the Perception DC to find such traps by (min(5,CASTERLEVEL/2)). Obscured script can be made permanent with a permanency spell by a caster of 10th level or higher for the cost of 5,000 gp.") },
    SpellListEntry { key: "Planar Inquiry", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(3), description: Some("[redacted PI]") },
    SpellListEntry { key: "Preserve Grace", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(1), description: Some("[redacted PI]") },
    SpellListEntry { key: "Rune of Rule", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("Investigations into the ancient and mysterious traditions of the seven virtues of rule of the lost human empire of Azlant, which were later corrupted by the runelords into the more familiar seven deadly sins, inspired the Cyphermages to develop the runes of rule. This spell allows you to place a rune upon another creature that can then be used to aid it at a later time. You determine the spell's effect at the time of casting by using your finger to paint a specific rune on the recipient's body with a dose of specially prepared paint worth 25 gp. The inscribed rune lasts for 24 hours or until the spell is activated. Unless otherwise noted, the creature upon which the rune of rule has been inscribed can activate it at any time as a swift action. If the spell effect isn't used, all markings associated with the rune disappear and the effect fades. You can never place the spell upon yourself-it must be bestowed on someone else. The seven runes of rule, along with their specific effects when the user activates them, are listed below. A creature can bear only one rune of rule at a time. [Charity] A creature bearing this mark gains a +5 insight bonus on a single attack roll or skill check attempted at the request of another creature, provided the creature bearing this mark does not gain any immediate benefit or reward for making the roll or attempting the check. [Generosity] A creature bearing the rune of generosity can activate it as an immediate action, but it must do so as another creature within 30 feet activates a consumable magic item such as a potion or scroll that was given to it at some point within the last 24 hours by the creature bearing the rune. When the rune is activated, the effects of the consumable magic item resolve at a caster level that is 2 higher than the item's actual caster level. [Humility] When a creature activates the rune of humility, it does not provoke attacks of opportunity for 1 round. [Kindness] A creature must be using the aid another action or casting a healing spell in order to activate a rune of kindness. If the creature activates the rune while using the aid another action, the bonus imparted on a success increases to +5. If the creature instead activates the rune while casting a healing spell, the effective caster level of the spell increases by 2. [Love] When a creature activates the rune of love as he casts a spell with the charm descriptor, the save DC of that spell increases by 1. Alternatively, a creature can activate the rune of love after he rolls damage for a weapon or spell attack, causing the damage dealt to become nonlethal damage. [Temperance] A creature bearing the rune of temperance can activate it as an immediate action immediately upon failing a saving throw against a poison, disease, drug, or similar effect. The creature can immediately attempt a second saving throw against the effect and can use the result of that second saving throw as the actual result. [Zeal] A creature that activates the rune of zeal gains a +3 bonus on Will saves, and the save DCs of all language-dependent effects created by the creature increase by 1; these effects last for 1 round. [Material Components] vial of paint worth 25 gp") },
    SpellListEntry { key: "Rune Trace", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(1), description: Some("By immersing yourself fully in the intricacies of a carved or written rune of any kind, you can divine the elements of that rune's nature. While casting rune trace, you must run your fingers (which cannot be gloved at the time) over the rune, glyph, symbol, or other marking you want to examine (hereafter referred to as the \"rune\"). This does not trigger any effects that touching the rune would normally trigger. Runes, symbols, and other effects that trigger when read still trigger as normal if you do so-but note that this spell does not require you to view and read the rune that you're targeting. When the spell's casting time ends, you instantly receive flashes of insight regarding the rune's nature, history, and purpose, including the following information. [Age] You learn if the rune was placed within the last 24 hours, within the last month, within the last year, within the last decade, within the last century, or prior to the last century. [Insight] If you have cast rune trace on a magical rune, you gain a +5 bonus on all skill rolls and checks to dispel, disable, or otherwise tamper with the rune. [Language] You learn what language the character of the rune is taken from, or in the case of a rune that has no language, you learn that it is a unique image. [Purpose] You learn the general purpose of the rune (such as whether it's a decoration, information, a magical defense, or a warning). [Material Components] pinch of powdered gemstones worth 25 gp") },
    SpellListEntry { key: "Codex-Named Unit (spell_adventurers_guide_ag_spells_lst_34)", name_pi_line: Some(34), school: Some(Pf1SchoolId::Divination), level: Some(6), description: Some("[redacted PI]") },
    SpellListEntry { key: "Sawtooth Terrain", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("This spell targets an area of earth, metal, stone, or wood, causing long, serrated blades to shoot out from random points within the area of effect. Any creature in the area when the spell is first cast must attempt a Reflex save to avoid taking 3d8 points of piercing damage from the blades and an additional 2d6 points of bleed damage. A creature that fails the save also has its speed reduced by half for 24 hours or until the injured creature benefits from a \"cure\" spell (which restores lost hit points as normal). Another creature can remove the penalty by succeeding on a Heal check against the spell's save DC as a standard action. The lashing limbs remain active in the area for the remainder of the spell's duration, during which time the area is treated as difficult terrain, and any creature that moves into or through the area takes 1d8 points of piercing damage. The transformed area can be located on any visible surface within range, including floors, walls, doors, ceilings, or other generally flat surfaces.") },
    SpellListEntry { key: "Shackle", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(2), description: Some("You summon a set of Small or Medium masterwork restraints into being. When you cast this spell, you can choose whether the restraints are manacles or fetters (manacles specifically designed to fit around the ankles). You also summon the restraints' key to your person; the Disable Device DC to open the locked restraints is equal to 15 + your caster level + the modifier of your primary casting ability score. Typically, the restraints appear in your hands. However, as part of the spell's casting, you can make a melee touch attack against a creature; if you succeed and the creature then fails a Reflex saving throw against the spell's DC, the locked fetters appear clasped on the creature or locked manacles clasp you and the creature together. You can instead have manacles restrain the target's limbs in front of or behind it. If you cast the spell as a full-round action, you can make melee touch attacks against two creatures you can reach. If you succeed at both attacks and both creatures fail their Reflex saving throws, you can cause the set of manacles to bind the targets together. As you increase in level, the restraints become stronger and you gain more control over them. If you are 6th level or higher, you can make the restraints mithral, or you can summon Tiny or Large restraints. If you are 12th level or higher, you can summon Diminutive or Huge restraints. If you use an emerald worth at least 1,000 gp as a material component while casting this spell, as a standard action once during its duration, you can affect any creature bound by these restraints as per dimensional anchor with a duration of (CASTERLEVEL) minutes. If you are 18th level or higher and use an emerald worth at least 1,000 gp as a material component while casting this spell, the restraints' hardness increases to 30, they have 60 hit points, and they can't be broken with a successful Strength check. (The emerald must be worth at least 2,000 gp if you also wish to use the dimensional anchor effect described earlier.) If you cast this spell before the duration of a previous casting has lapsed, you can create a new set of restraints or reset the previous spell's duration. If you used an expensive material component during a previous casting, you must again use a component when creating new restraints or resetting the duration if you wish to maintain the special effect. You do not need to touch these previously created shackles to renew their duration, though you must be on the same plane as the shackles. When this spell ends, the restraints disappear, and any ongoing effects created by the spell end.") },
    SpellListEntry { key: "Slave to Sin", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(2), description: Some("This spell allows you to reach into an evil creature's mind to expose and exploit its susceptibility to whichever of the seven so-called \"deadly sins\" it is most susceptible to. The targeted creature must succeed at a Will save or it is overwhelmed with an inability to repress urges to indulge in whatever sin most closely mirrors its personality, and a glowing rune appears upon the creature's body (usually the brow), identifying the sin. (The GM adjudicates which rune manifests on the creature's body, as appropriate.) Each round, at the start of its turn, the target must attempt a new Will saving throw against the spell's DC to resist the sin's enslavement. If the target succeeds at this saving throw, it is sickened for that round by the distractions of its sin. If it fails, it is sickened and staggered as it spends part of its action wallowing in its targeted sin (a wrathful victim might waste time spouting threats and profanity, while a slothful victim might merely be slow and hesitant, and a lustful victim could well spend precious moments ogling or fawning over something of beauty).") },
    SpellListEntry { key: "Storm Sight", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(2), description: Some("You step into any magical or naturally occurring storm and commune directly with the power of the wind and rain. This spell allows the storm's power to fill you, granting you knowledge and images of what else lies within its reach. As long as you remain within the storm, you can concentrate on it for 1 minute to determine whether or not other living creatures with an Intelligence score of 3 or higher are caught in the storm within 400 feet of you. Due to the nature of the spell, you do not need to attempt concentration checks against violent wind or storms when casting the spell, but other elements that might disrupt spellcasting require checks as normal. While the spell is in effect, you no longer need to attempt concentration checks as a result of wind or storms for spells you cast or concentrate on. Once you've sensed creatures with this spell by concentrating for 1 minute, you can continue concentrating to learn more. After you concentrate for 1 additional round, the spell reveals to you via winds and rain the presence of any Small or larger living creature with an Intelligence of 3 or higher within 400 feet of you. After 2 consecutive rounds of concentration, you learn the approximate distance to the detected life forms from your current location. After 3 rounds of concentration, the rain and winds allow you to determine the approximate direction of each life form. Once you've concentrated in this way for 3 rounds, you gain a bonus equal to half your caster level on your next initiative check during the spell's duration.") },
    SpellListEntry { key: "Summon Flight of Eagles", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(4), description: Some("You summon 1d4+1 giant eagles to serve as you designate. The summoned birds can fight if you wish, but can also serve as mounts. [Material Components] a gold feather worth 100 gp") },
    SpellListEntry { key: "Sun's Disdain", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("You alter a creature so the touch of the sun is hostile to it. The cursed creature gains light blindness and is blinded for 1 round if exposed to bright light, such as sunlight or the daylight spell. The cursed creature is dazzled as long as it remains in areas of bright light, and it is treated as being particularly susceptible to sunlight for the purposes of resolving spells like searing light, sunbeam, and sunburst.") },
    SpellListEntry { key: "Sun's Disdain (Mass)", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("You alter multiple creatures so the touch of the sun is hostile to them. The cursed creatures gain light blindness and are blinded for 1 round if exposed to bright light, such as sunlight or the daylight spell. The cursed creatures are dazzled as long as they remains in areas of bright light, and they are treated as being particularly susceptible to sunlight for the purposes of resolving spells like searing light, sunbeam, and sunburst.") },
    SpellListEntry { key: "Sunstalker", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(3), description: Some("A touched creature becomes invisible (as per invisibility) as long as it is in direct sunlight (or bright light shed by a daylight spell). If an action the target creature takes causes the invisible creature to become visible but does not end the sunstalker spell's duration, the creature can use this spell's magic to become invisible again as a standard action as long as it stands in an area of sunlight (as defined above). The creature gains only concealment (20%% miss chance) in normal light.") },
    SpellListEntry { key: "Suppress Charms and Compulsions", name_pi_line: None, school: Some(Pf1SchoolId::Abjuration), level: Some(2), description: Some("You bolster the subject's sense of willpower and self-worth when you cast this spell. As you cast it, you must decide if you want to grant a bonus to saving throws against charms and compulsions or suppress charms and compulsions. If you grant a bonus to saving throws, you grant all affected creatures a +4 morale bonus on saving throws against charm and compulsion effects for 10 minutes. If instead you suppress charms and compulsions, the spell's duration drops to concentration, to a maximum duration of (CASTERLEVEL) rounds. As long as you continue to concentrate, the spell suppresses all existing charm and compulsion effects affecting the targets, regardless of whether the effect is beneficial or harmful. New charm or compulsion effects that successfully target such a protected creature are automatically suppressed as long as you continue concentrating. If you cease concentrating, the spell effect immediately ends, and remaining charm or compulsion effects resume for the rest of their remaining durations as normal.") },
    SpellListEntry { key: "Sympathetic Aura", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(2), description: Some("This spell functions like magic aura, except it extends its altered aura to similar items in a 5-foot radius. For this purpose, similar items must be alike in approximate shape, composition, and function, so a potion of cure light wounds targeted by this spell to appear nonmagical would also obscure the auras of nearby potions, elixirs, and oils, as well as flasks. Items other than the targeted item retain their altered aura for (CASTERLEVEL) rounds after being removed from the spell's area.") },
    SpellListEntry { key: "Tactical Adaptation", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(3), description: Some("[redacted PI]") },
    SpellListEntry { key: "Codex-Named Unit (spell_adventurers_guide_ag_spells_lst_46)", name_pi_line: Some(46), school: Some(Pf1SchoolId::Enchantment), level: Some(2), description: Some("With a lascivious wink and a sensuous sway, you flood a foe's mind with lustful thoughts of you, distracting your target and rendering that creature vulnerable to your attacks. An affected creature takes a -(CASTERLEVEL/2) penalty on concentration checks and to its CMD against dirty trick, grapple, and steal combat maneuvers you perform. The creature is also denied its Dexterity bonus to AC for the first melee attack you make against it each round. If the target would not normally be sexually attracted to you, it receives a +4 bonus on its saving throw. If you end your turn more than 20 feet from the target or end your turn where your target cannot see you, this spell immediately ends.") },
    SpellListEntry { key: "Wall of Silver", name_pi_line: None, school: Some(Pf1SchoolId::Abjuration), level: Some(5), description: Some("You create a wall of translucent silver energy that hums and vibrates at the slightest touch. Objects and nonevil creatures can pass through this wall without difficulty. However, spells and effects with the evil descriptor treat this barrier as a wall of force, which blocks line of effect. Evil creatures that pass through the wall take 3d6+(min(20,CASTERLEVEL)) points of damage and are blinded for 1 round. Creatures of any alignment that are particularly vulnerable to silver (such as those with damage reduction bypassed by silver, like devils or lycanthropes) instead take (min(15,CASTERLEVEL))d6 points of damage, are staggered for 1 round, and are permanently blinded. A creature that succeeds at a Will save reduces the damage by half and negates the blinding and staggering effects. If you create a wall of silver so that it appears where creatures are, each creature takes damage as if passing through the wall. Each such creature can avoid the wall (ending up on the side of its choice) and thus take no damage by succeeding at a Reflex save.") },
    SpellListEntry { key: "Continual Flame (Lantern Bearer)", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: None, description: Some("A flame, equivalent in brightness to a torch, springs forth from an object that you touch. If within 20 feet of a continual flame you created using this ability, you can extinguish it to cast searing light.") },
    SpellListEntry { key: "Summon Mantis", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: None, description: Some("This spell summons your choice of one extraplanar advanced fiendish giant mantis, 1d3 fiendish giant mantises, or 1d4+1 giant mantises. They appear where you designate and act immediately, on your turn. You can mentally direct the actions of these summoned vermin as a free action. All mantises summoned by this spell-like ability are blood red, and gain no racial bonus on Stealth checks in forests. Creatures cannot be summoned into an environment that cannot support them. If you use this spell to summon fiendish mantises, it is an evil spell.") },
];
